import {editorMarkup,mountEditor} from './editor.js';
import {migrateTree,layoutTree} from './graph-model.js';
import {AVATARS,AVATAR_IDS,avatarFor,avatarSvg} from './avatars.js';
const SESSION='cupid-session',LEGACY='cupid-lab-v1';
const store={get:k=>{try{return localStorage.getItem(k)}catch{return null}},set:(k,v)=>{try{v==null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch{}}};
let token=store.get(SESSION)||'',me=null,tab='tree',authMode='login',data={},skipped=new Set(),saving=Promise.resolve();
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3400)}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{Authorization:'Bearer '+token,...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json().catch(()=>({error:'Unexpected server response.'}));if(r.status===401&&!path.match(/^(login|register)$/)){signedOut();throw Error('Your session ended. Sign in again.');}if(!r.ok)throw Error(result.error);return result;}
function signedOut(){token='';me=null;data={};store.set(SESSION,null);render();}
const pages={tree:'My tree',profile:'Profile',appearance:'Attraction',questions:'Questions',simulate:'Matches'};
const icons={tree:'M4 4h6v5H4z M14 15h6v5h-6z M4 15h6v5H4z M7 9v3h10v3 M7 12v3',profile:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 8 0 0 1 16 0v2',appearance:'M12 20S3 14 3 8a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6-9 12-9 12Z',questions:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',simulate:'m8 4 12 8-12 8z'};
const pic=(u,size)=>avatarSvg(u.avatar,u.id,size);
function render(){
 if(!me){app.innerHTML=authPage();bindAuth();return;}
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">Formula:Love</div><nav class="nav">${Object.entries(pages).map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[id]}"/></svg>${label}</button>`).join('')}</nav><div class="sidefoot">Prototype · your rules stay private.</div></aside><main class="workspace"><header class="topbar"><div class="context">Formula:Love <span>/</span> <strong>${pages[tab]}</strong></div><div class="person-switch">${pic(me,26)}<span class="small">${esc(me.username)}</span><button class="ghost" data-action="logout">Sign out</button></div></header><div class="page">${{tree:treePage,profile:profilePage,appearance:appearancePage,questions:questionsPage,simulate:matchesPage}[tab]()}</div></main></div>`;
 bind();if(tab==='tree')mountEditor(me.tree,tree=>{me.tree=tree;render();saveTree(tree);},toast);
}
function authPage(){const login=authMode==='login';return `<main class="auth"><div class="brand">Formula:Love</div><h1>${login?'Sign in':'Create your account'}</h1><p class="muted">Design your own matchmaking algorithm. Your rules stay private.</p><form id="auth-form" class="card"><label class="field"><span>Username</span><input name="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+"><small class="hint">${login?'':'Public: 3–32 letters, digits or underscores.'}</small></label><label class="field"><span>Password</span><input name="password" type="password" minlength="10" maxlength="256" autocomplete="${login?'current-password':'new-password'}" required>${login?'':'<small class="hint">At least 10 characters.</small>'}</label><p id="auth-error" class="error" role="alert"></p><button class="primary">${login?'Sign in':'Create account'}</button></form><p class="small muted">${login?'New here?':'Already have an account?'} <a href="#" data-auth="${login?'register':'login'}">${login?'Create an account':'Sign in'}</a></p></main>`}
function bindAuth(){document.querySelector('[data-auth]').onclick=e=>{e.preventDefault();authMode=e.target.dataset.auth;render();};document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;try{const session=await api(authMode,'POST',{username:f.get('username'),password:f.get('password')});token=session.token;store.set(SESSION,token);await loadMe();go('tree');}catch(err){document.querySelector('#auth-error').textContent=err.message;button.disabled=false;}};}
// Trees drawn before the editor ran left to right are rearranged once, then flagged.
function toLeftToRight(tree){if(tree.layout==='ltr')return false;if(tree.nodes.length)layoutTree(tree);tree.layout='ltr';return true;}
async function loadMe(){me=await api('me');me.tree=migrateTree(me.tree);if(toLeftToRight(me.tree))saveTree(me.tree);}
// Saves run in order so a slow request never overwrites a newer tree.
function saveTree(tree){const body=JSON.parse(JSON.stringify(tree));saving=saving.then(()=>api('tree','PUT',body)).catch(e=>toast('Not saved: '+e.message));return saving;}
async function load(names){try{const results=await Promise.all(names.map(n=>api(n)));names.forEach((n,i)=>data[n]=results[i]);}catch(e){toast(e.message);}render();}
function go(next){tab=next;history.replaceState(null,'','#'+next);render();const needs={appearance:['candidates'],questions:['questions'],simulate:['progress','matches','questions']}[next];if(needs)load(needs);}
function title(name,desc,actions=''){return `<div class="pagehead"><div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function legacyTree(){if(store.get('cupid-import-dismissed')||me.tree.nodes.length)return null;try{const tree=JSON.parse(store.get(LEGACY))?.profiles?.find(p=>p.id==='you')?.tree;return tree?.nodes?.length?tree:null;}catch{return null;}}
function treePage(){const legacy=legacyTree();return title('My tree','Questions supply answers. Blocks combine them into your rules.','<button data-action="export">Export tree</button><button class="primary" data-tab="simulate">View matches</button>')+(legacy?`<div class="notice">This browser has a tree from before accounts (${legacy.nodes.length} nodes). <button data-action="import-legacy">Import it</button> <button class="ghost" data-action="dismiss-legacy">Dismiss</button></div>`:'')+editorMarkup(me.tree,me.id);}
function input(label,name,value,hint=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}">${hint?`<small class="hint">${hint}</small>`:''}</label>`}
function profilePage(){const current=avatarFor(me.avatar,me.id);return `${title('Profile','Everyone sees your username and picture. The rest waits for a mutual match.')}<form id="profile-form"><div class="cards"><section class="card"><h2>Public profile</h2><p class="muted small">Shown to everyone, including on responses you send.</p><div class="profile-heading">${pic(me,52)}<div><strong>${esc(me.username)}</strong><div class="small muted">${esc(AVATARS[current].label)}</div></div></div><div class="field"><span>Picture</span><div class="avatar-grid" role="radiogroup" aria-label="Profile picture">${AVATAR_IDS.map(id=>`<label class="avatar-option"><input type="radio" name="avatar" value="${id}" ${id===current?'checked':''}>${avatarSvg(id,'',36)}<span>${esc(AVATARS[id].label)}</span></label>`).join('')}</div><small class="hint">Custom pictures are coming later.</small></div><hr class="sectionline"><h3>Revealed after a match</h3>${input('Name','name',me.name)}<label class="field"><span>About you</span><textarea name="bio" rows="4">${esc(me.bio)}</textarea></label><label class="field"><span>Public hobbies</span><textarea name="publicHobbies" rows="3">${esc(me.publicHobbies)}</textarea><small class="hint">Separate interests with commas.</small></label></section><section class="card"><span class="badge">Private</span><h2 style="margin-top:12px">Private context</h2><p class="muted small">Used for matching, never shown to anyone.</p><label class="field"><span>Private hobbies</span><textarea name="privateHobbies" rows="4">${esc(me.privateHobbies)}</textarea></label><label class="field"><span>Minimum attraction rating</span><input name="attractionThreshold" type="number" min="1" max="10" step="1" value="${me.attractionThreshold}"><small class="hint">You both need to rate each other at least this high to match.</small></label><div class="note-card"><h3>How hobby matching works</h3><p>A hobby condition compares both lists. A match can see that compatible interests exist, without seeing the hidden hobby names.</p></div><p class="privacy">Signed in with: ${me.identities.map(p=>p==='password'?'username and password':esc(p)).join(', ')}. Google, Discord and LinkedIn sign-in are planned.</p></section></div><div class="export-row"><button type="submit" class="primary">Save profile</button></div></form>`}
function appearancePage(){const list=data.candidates;return `${title('Attraction','A private rating for each person. Nobody sees your scores.')}<section class="card">${!list?'<p class="muted">Loading…</p>':!list.length?'<p class="muted">No one else has an account yet.</p>':`<ul class="people">${list.map(c=>`<li>${pic(c,32)}<strong>${esc(c.username)}</strong><select data-rate="${esc(c.id)}" aria-label="Rating for ${esc(c.username)}"><option value="">Not rated</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${c.score===i+1?'selected':''}>${i+1} / 10</option>`).join('')}</select></li>`).join('')}</ul>`}<p class="privacy">Photo uploads are not connected yet, so ratings use public profile pictures for now.</p></section>`}
function questionControl(q){if(q.type==='scale')return `<form class="choices" id="number-answer"><input class="text number-input" name="value" type="number" inputmode="decimal" required step="${q.integer?1:'any'}" ${q.min!=null?`min="${q.min}"`:''} ${q.max!=null?`max="${q.max}"`:''} aria-label="Your answer" placeholder="${q.min!=null&&q.max!=null?`${q.min}–${q.max}`:q.integer?'Whole number':'Number'}"><button class="primary">Answer</button></form>`;if(q.type==='boolean')return `<div class="choices"><button data-answer="true">Yes</button><button data-answer="false">No</button></div>`;if(q.type==='category')return `<div class="choices">${q.options.map((o,i)=>`<button data-option="${i}">${esc(o)}</button>`).join('')}</div>`;return ''}
function questionCard(){const list=data.questions;if(!list)return '<section class="card"><p class="muted">Loading…</p></section>';const q=list.find(q=>!skipped.has(q.token));return `<section class="card" style="max-width:650px">${q?`<span class="eyebrow">From someone's tree</span><h2 style="margin-top:6px">${esc(q.label)}</h2>${questionControl(q)}<button class="ghost" data-skip="${esc(q.token)}">Skip for now</button>`:'<p class="muted">No questions right now. Check back after more people build their trees.</p>'}</section>`}
function questionsPage(){return title('Questions','Answer at your own pace. Skip anything you like.')+questionCard();}
function matchesPage(){const p=data.progress,m=data.matches;return title('Matches','How far you and others get through each other’s trees.')+`<div class="card" style="margin-bottom:16px">${p?`<p>Furthest anyone has reached in your tree: <strong>${p.incoming.passed}/${p.incoming.total}</strong></p><p>Furthest you have reached in someone else’s tree: <strong>${p.outgoing.passed}/${p.outgoing.total}</strong></p><small class="muted">Decision nodes only, along the best compatible route.</small>`:'<p class="muted">Loading…</p>'}</div><section class="card" style="margin-bottom:16px"><h2>Mutual matches</h2>${!m?'<p class="muted">Loading…</p>':!m.length?'<p class="muted">No mutual matches yet.</p>':`<ul class="people">${m.map(x=>`<li>${pic(x,32)}<div><strong>${esc(x.name)}</strong> <span class="small muted">@${esc(x.username)}</span>${x.bio?`<p class="small">${esc(x.bio)}</p>`:''}${x.publicHobbies?`<p class="small muted">${esc(x.publicHobbies)}</p>`:''}</div></li>`).join('')}</ul>`}</section>`+questionCard();}
async function answer(value){const q=data.questions.find(q=>!skipped.has(q.token));try{await api('answers','POST',{token:q.token,value});await load(tab==='simulate'?['questions','progress','matches']:['questions']);}catch(e){toast(e.message);}}
function bind(){
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 document.querySelectorAll('[data-skip]').forEach(b=>b.onclick=()=>{skipped.add(b.dataset.skip);render();});
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.answer==='true'));
 document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>answer(data.questions.find(q=>!skipped.has(q.token)).options[b.dataset.option]));
 document.querySelector('#number-answer')?.addEventListener('submit',e=>{e.preventDefault();answer(Number(e.target.elements.value.value));});
 document.querySelectorAll('[data-rate]').forEach(s=>s.onchange=async()=>{try{await api('rating','PUT',{targetId:s.dataset.rate,score:s.value?Number(s.value):null});data.candidates.find(c=>c.id===s.dataset.rate).score=s.value?Number(s.value):null;toast('Rating saved.');}catch(e){toast(e.message);}});
 document.querySelector('#profile-form')?.addEventListener('change',e=>{if(e.target.name==='avatar'){me.avatar=e.target.value;render();}});
 document.querySelector('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.attractionThreshold=Number(f.attractionThreshold);try{const tree=me.tree;me=await api('profile','PUT',f);me.tree=tree;render();toast('Profile saved.');}catch(err){toast(err.message);}});
}
async function action(a){
 if(a==='logout'){try{await api('logout','POST',{});}catch{}signedOut();}
 else if(a==='export'){const blob=new Blob([JSON.stringify(me.tree,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='formula-love-tree.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 else if(a==='dismiss-legacy'){store.set('cupid-import-dismissed','1');render();}
 else if(a==='import-legacy'){const tree=migrateTree(JSON.parse(JSON.stringify(legacyTree())));toLeftToRight(tree);try{await api('tree','PUT',tree);me.tree=tree;store.set('cupid-import-dismissed','1');render();toast('Tree imported to your account.');}catch(e){toast('Could not import: '+e.message);}}
}
const start=location.hash.slice(1);if(start in pages)tab=start;
if(token)loadMe().then(()=>go(tab),()=>{if(token)signedOut();});else render();
